S = "Hakeem Force Academy"
QS = [
(S, "Rearrange the letters YTUEAB to form a word. Which word is it?", ["Beauty", "Bayute", "Tuebay", "Abuety"], 0, "The letters Y, T, U, E, A, B can be arranged to spell BEAUTY.", "Beauty is a noun meaning the quality of being pleasing to the senses or mind.", 1),
(S, "Rearrange the letters RPALODE to form the name of an animal.", ["Leopard", "Lopared", "Pardole", "Leorpad"], 0, "The letters R, P, A, L, O, D, E rearrange to LEOPARD.", "The leopard is a big cat found in Africa and Asia.", 1),
(S, "Rearrange the letters RSPAI to get the name of a city.", ["Rome", "Paris", "Sipra", "Parsi"], 1, "The letters R, S, P, A, I rearrange to PARIS.", "Paris is the capital of France, on the river Seine.", 1),
(S, "Sheep is to wool as cat is to what?", ["Fur", "Milk", "Silk", "Leather"], 0, "Wool is the covering that grows on a sheep, and fur is the covering that grows on a cat.", "Wool is obtained by shearing sheep.", 1),
(S, "Speak is to hear as look is to what?", ["Eye", "See", "Watch", "Sound"], 1, "Speaking is matched by hearing, and looking is matched by seeing, the result received.", "Hearing is the sense of the ear and seeing is the sense of the eye.", 1),
(S, "What is the approximate value of the square root of 3?", ["1.414", "1.618", "1.732", "2.236"], 2, "1.732 x 1.732 is about 3.0, so the square root of 3 is about 1.732.", "The square root of 2 is about 1.414 and of 5 is about 2.236.", 1),
(S, "The cube of unity (1 cubed) is equal to what?", ["0", "1", "3", "Minus 1"], 1, "1 x 1 x 1 = 1, so the cube of unity is 1.", "The three cube roots of unity are 1 and two complex numbers, each of which also cubes to 1.", 1),
(S, "The population of a village was 2000 in the year 2000. If it doubled every five years, what was its population in 1980?", ["125", "250", "500", "100"], 0, "From 1980 to 2000 is 20 years, which is 4 doublings. So the 1980 population is 2000 / 2 / 2 / 2 / 2 = 125.", "Going back in time, a doubling quantity is halved each period.", 1),
(S, "In division, the remainder is always less than which number?", ["The quotient", "The dividend", "The divisor", "Zero"], 2, "If the remainder were equal to or larger than the divisor, the divisor could be taken once more, so the remainder is always smaller than the divisor.", "When the remainder is zero, the dividend is exactly divisible by the divisor.", 1),
(S, "There are 30 people in a room and 2/3 of them are men. How many are women?", ["20", "15", "10", "5"], 2, "Men = 2/3 x 30 = 20, so women = 30 - 20 = 10.", "The women are 1/3 of the total, and 1/3 of 30 is 10.", 3),
(S, "Today is Monday the 1st of the month. What day will it be on the 12th of the month?", ["Thursday", "Wednesday", "Saturday", "Friday"], 3, "The 12th is 11 days after the 1st. 11 divided by 7 leaves remainder 4, and 4 days after Monday is Friday.", "A week has 7 days, so the same weekday repeats every 7 days.", 1),
(S, "Today is Sunday. What will be the day after tomorrow?", ["Monday", "Tuesday", "Wednesday", "Saturday"], 1, "Tomorrow is Monday, so the day after tomorrow is Tuesday.", "In Pakistan the working week traditionally runs Monday to Friday.", 1),
(S, "Total students are 1500 and 1200 of them are female. What is the percentage of females?", ["75%", "85%", "70%", "80%"], 3, "1200 / 1500 x 100 = 80%.", "Percentage means per hundred.", 1),
(S, "There are 24 students and 1/4 of them are male. What is the percentage of females?", ["25%", "75%", "60%", "80%"], 1, "Males are 1/4 = 25%, so females are 100 - 25 = 75% (18 of 24).", "1/4 equals 25 percent.", 1),
(S, "Total students in a class are 1500 and 1200 are present. What is the percentage of absent students?", ["25%", "30%", "15%", "20%"], 3, "Absent = 1500 - 1200 = 300. 300 / 1500 x 100 = 20%.", "Present and absent percentages add up to 100%.", 1),
(S, "What are the two square roots of 64?", ["8 and -8", "4 and -4", "16 and -16", "32 and -32"], 0, "8 x 8 = 64 and (-8) x (-8) = 64, so the roots are +8 and -8.", "Every positive number has two square roots, one positive and one negative.", 1),
(S, "What is 10% of 80?", ["8", "10", "80", "0.8"], 0, "10% of 80 = 80 / 10 = 8.", "To find 10% of a number, divide it by 10.", 1),
(S, "What is 1/10 of 120?", ["10", "14", "1.2", "12"], 3, "120 / 10 = 12.", "One tenth is the same as 10 percent.", 1),
(S, "What is the value of 1 - 2 + 2/2?", ["0", "3", "1", "-1"], 0, "Division first: 2/2 = 1. Then 1 - 2 + 1 = 0.", "BODMAS: brackets, orders, division and multiplication, then addition and subtraction.", 1),
(S, "What is 1/3 of 120?", ["30", "36", "40", "4"], 2, "120 / 3 = 40.", "One third of 120 is ten times larger than one third of one tenth of 120, which is 4.", 1),
(S, "What is 1/3 of 36?", ["9", "12", "13", "18"], 1, "36 / 3 = 12.", "36 is divisible by 2, 3, 4, 6, 9, 12 and 18.", 1),
(S, "What is the value of 2 + 2 x 2?", ["8", "6", "4", "10"], 1, "Multiplication comes first: 2 x 2 = 4, then 2 + 4 = 6.", "BODMAS gives multiplication priority over addition.", 1),
(S, "What is the value of 2 + 3/3?", ["3", "2", "5/3", "1"], 0, "Division first: 3/3 = 1, then 2 + 1 = 3.", "Division is done before addition under BODMAS.", 1),
(S, "What is the value of 2 x 3 + 3 x 6?", ["30", "24", "18", "36"], 1, "2 x 3 = 6 and 3 x 6 = 18, so 6 + 18 = 24.", "Both multiplications are done before the addition.", 1),
(S, "What is 30% of 20?", ["5", "6", "60", "10"], 1, "30/100 x 20 = 6.", "30% of 20 is 3 times 10% of 20, which is 2.", 1),
(S, "What is the value of 3 + 3 x 3?", ["18", "9", "12", "27"], 2, "Multiplication first: 3 x 3 = 9, then 3 + 9 = 12.", "Without BODMAS, one would wrongly compute (3 + 3) x 3 = 18.", 1),
(S, "What is 60% of 80?", ["52", "48", "50", "40"], 1, "60/100 x 80 = 48.", "60% is the same as 3/5, and 3/5 of 80 is 48.", 1),
(S, "What is 90% of 9?", ["81", "0.81", "8.1", "7.2"], 2, "90/100 x 9 = 8.1.", "90% of a number is the number minus 10% of it, so 9 - 0.9 = 8.1.", 1),
(S, "What is a chord that passes through the centre of a circle called?", ["Radius", "Diameter", "Tangent", "Arc"], 1, "A chord through the centre is the longest chord of the circle and is called the diameter.", "The diameter is twice the radius.", 1),
(S, "What is a quarter of one tenth of 90?", ["2.25", "3", "22.5", "9"], 0, "One tenth of 90 is 9, and a quarter of 9 is 9 / 4 = 2.25.", "A quarter of one tenth is 1/40 of the number.", 1),
(S, "What is an angle greater than 90 degrees (and less than 180 degrees) called?", ["Acute angle", "Right angle", "Reflex angle", "Obtuse angle"], 3, "An angle between 90 and 180 degrees is obtuse.", "An angle of exactly 180 degrees is a straight angle.", 1),
(S, "What is an angle less than 90 degrees called?", ["Obtuse angle", "Acute angle", "Right angle", "Straight angle"], 1, "An angle smaller than 90 degrees is called an acute angle.", "Two acute angles can add up to 90 degrees, in which case they are complementary.", 1),
(S, "What is a matrix whose entries are all zero called?", ["Identity matrix", "Scalar matrix", "Null matrix", "Diagonal matrix"], 2, "A matrix with every element equal to zero is called a null (zero) matrix.", "Adding a null matrix to any matrix of the same order leaves it unchanged.", 1),
(S, "What is the value of cos 90 degrees?", ["1", "0", "-1", "Undefined"], 1, "On the unit circle, the point at 90 degrees is (0, 1), and its x-coordinate, the cosine, is 0.", "Sin 90 degrees equals 1.", 1),
(S, "What is cos x multiplied by tan x equal to?", ["Cos x", "Tan x", "Sin x", "Cot x"], 2, "Since tan x = sin x / cos x, cos x times tan x = sin x.", "Another identity: sin x divided by cos x equals tan x.", 1),
]
